/**
 * Native SingleBitPerPixelGridFit DrawString paragraphs, regenerated by
 * `scripts/gdi-fixtures/generate-drawstring-wrap.ts`: Arial in a layout
 * rectangle, played back by GDI+ one device pixel per pixel. Lines break at
 * CR/LF and, measured by the tracked design advances with kerning, after
 * spaces or between the characters of a word longer than a line; line n's
 * baseline is the layout top plus the design ascent and n hhea line
 * spacings, rounded; wrapped lines are kerned (whole pixels per pair); a line
 * is laid out when a quarter of it is inside the rectangle, the last one
 * filled by characters (Character trimming), and the text is clipped to the
 * rectangle.
 */
import { readFileSync } from 'node:fs';
import { gunzipSync } from 'node:zlib';
import { createCanvas, loadImage } from '@napi-rs/canvas';
import { beforeAll, describe, expect, it } from 'vitest';
import { windowsFonts } from './__fixtures__/gdi-parity-harness';
import { ensureNodeCanvasModule } from './emf-canvas-helpers';
import { convertMetafileToDataUrl } from './emf-converter';
import { layoutPlusLines } from './emf-plus-text-image-handlers';

const fixture: { width: number; height: number; captures: Array<{ name: string; emf: string; ink: string }> } = JSON.parse(
	gunzipSync(readFileSync(new URL('./__fixtures__/gdi/text-drawstring-wrap.json.gz', import.meta.url))).toString(),
);
const fontBytes = windowsFonts();

/**
 * Open: inside the character-trimmed last line native widens the spaces (a pixel at 16 px, two at 24 px) and does
 * not kern; the line holds the right characters. Pinned to the measured pixel counts.
 */
const OPEN: Record<string, number> = { 'sentence-em24-w120': 386, 'height-42': 24, 'height-45': 46, 'height-59': 94 };

beforeAll(async () => {
	await ensureNodeCanvasModule();
});

describe('layoutPlusLines()', () => {
	const codes = (s: string) => Array.from(s, (c) => c.charCodeAt(0));
	const lines = (s: string, available: number) =>
		layoutPlusLines(codes(s), codes(s).map(() => 10), available).map((l) => s.slice(l.start, l.end));

	it('breaks at CR, LF and CRLF', () => {
		expect(lines('AB\r\nCD\nEF\rGH', Infinity)).toEqual(['AB', 'CD', 'EF', 'GH']);
	});

	it('wraps after spaces and drops the spaces at a wrap', () => {
		expect(lines('AB CD   EF', 50)).toEqual(['AB CD', 'EF']);
	});

	it('breaks a word longer than a line between characters', () => {
		expect(lines('ABCDEFG', 30)).toEqual(['ABC', 'DEF', 'G']);
	});

	it('keeps a single line whole', () => {
		expect(lines('AB CD', 50)).toEqual(['AB CD']);
	});
});

describe.skipIf(!fontBytes)('native SingleBitPerPixelGridFit DrawString paragraphs', () => {
	it.each(fixture.captures.map((c) => [c.name, c]))('lays out %s', async (name, c) => {
		const { width: w, height: h } = fixture;
		const emf = Buffer.from(c.emf, 'base64');
		const url = await convertMetafileToDataUrl(emf.buffer.slice(emf.byteOffset, emf.byteOffset + emf.byteLength), { fonts: fontBytes! });
		const img = await loadImage(Buffer.from(url!.slice(url!.indexOf(',') + 1), 'base64'));
		const canvas = createCanvas(w, h);
		const g = canvas.getContext('2d');
		g.fillStyle = '#fff';
		g.fillRect(0, 0, w, h);
		g.drawImage(img, 0, 0);
		const d = g.getImageData(0, 0, w, h).data;
		const native = Buffer.from(c.ink, 'base64');
		let differing = 0;
		for (let i = 0; i < w * h; i++) {
			const ours = d[i * 4] > 128 && d[i * 4 + 1] < 128;
			if (ours !== ((native[i >> 3] >> (i & 7)) & 1) > 0) differing++;
		}
		expect(differing).toBeLessThanOrEqual(OPEN[name] ?? 0);
	});
});
